let i = 1;            // инициализация счётчика
while (i <= 5) {      // условие ПЕРЕД каждой итерацией
  console.log(i);     // тело: вывод текущего значения
  i++;                // шаг: увеличиваем счётчик на 1
}
// Вывод: 1, 2, 3, 4, 5

// Что будет если убрать i++? Условие всегда true → бесконечный цикл!

let n = 10;
do {
  console.log(n);     // тело выполняется СНАЧАЛА
  n -= 3;             // шаг: уменьшаем на 3
} while (n > 0);      // условие ПРОВЕРЯЕТСЯ ПОСЛЕ тела

// Вывод: 10, 7, 4, 1 — при n = -2 условие ложно, цикл останавливается
// Если бы условие было сразу ложно (n = -1), тело всё равно выполнилось бы один раз

// for (инициализация; условие; шаг) — три части в одной строке
for (let i = 0; i < 5; i++) {
  console.log("Итерация " + i);
}

// Как это читается движком:
// 1. let i = 0          — один раз в начале
// 2. i < 5              — перед КАЖДОЙ итерацией
// 3. тело цикла
// 4. i++                — ПОСЛЕ каждой итерации
// 5. повторить с шага 2

// Вывод: Итерация 0, 1, 2, 3, 4 — но не 5, потому что 5 < 5 это false

// Найти первое число, которое делится на 7 и больше 20
for (let i = 1; i < 1000; i++) {
  if (i % 7 === 0 && i > 20) {
    console.log("Нашли:", i);   // 21
    break;  // цикл остановлен — не крутим до 1000!
  }
}
// Вывод: 21

// Без break цикл сделал бы 1000 итераций вместо 21

// Вывести только нечётные числа
for (let i = 1; i <= 5; i++) {
  if (i % 2 === 0) {
    continue;  // чётное — пропустить остаток итерации
  }
  console.log(i);  // выполнится только для нечётных
}
// Вывод: 1, 3, 5 (чётные 2 и 4 пропущены)

// Разница break vs continue:
// break: цикл УМЕР — выход наружу
// continue: цикл ЖИВ — просто эта итерация пропущена

