// Таблица умножения 3x3
for (let i = 1; i <= 3; i++) {        // внешний: строки
  for (let j = 1; j <= 3; j++) {      // внутренний: столбцы
    console.log(`${i} * ${j} = ${i * j}`);
  }
}
// 9 строк вывода: 3 итерации внешнего × 3 внутреннего

// Для каждой i внутренний цикл проходит j = 1, 2, 3 полностью

